"All the music strengths together. Measured on this studio's takes: the score came out whole up to {0} in every run, broken from 2.5 in every run. Green to {1}, amber to {2}, red past it.": "Все музыкальные силы вместе. Замерено на семплах этой студии: партитура выходила целой до {0} в каждом запуске и сломанной от 2.5 в каждом. Зелёный до {1}, жёлтый до {2}, дальше красный.",
