"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0}: {1} на музыкальной половине — выше её предела {2}: партитура обычно ломается после 70–200 токенов.",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0}: {1} на звуковой половине — выше её предела {2}.",
"⚠ {0} plans instrumental scores: at {1} with words to sing, the score loses its vocal line (measured at 1.00: 1 note in 127 vocal bars, the music looping). Keep it low, 0.3–0.5, for a sung song.": "⚠ {0} планирует инструментальные партитуры: на {1} со словами для пения партитура теряет вокальную линию (замер на 1.00: 1 нота на 127 вокальных тактов, музыка зацикливается). Для песни с пением держи низко, 0.3–0.5.",
