"Drag: the form takes 55 to 70 % of the width; below 55 the takes take 60 % and the form one column · double-click: the default": "Тяни: форма берёт от 55 до 70 % ширины; ниже 55 семплы берут 60 %, а форма встаёт в одну колонку · двойной щелчок — по умолчанию",
"the transcriber": "транскрибер",
"written from its sound by {0}": "записана по звуку — {0}",
